import { describe, expect, it } from "vitest";
import {
  formatJalaliDate,
  gregorianToJalali,
  isLeapJalaaliYear,
  jalaliMonthLength,
  jalaliParts,
  jalaliToGregorian,
} from "@/lib/jalali";

/**
 * The pure Jalali converter must be output-identical to the Doran-backed
 * formatter it replaced. Reference anchors are independently published
 * calendar facts (Nowruz dates, month arithmetic, the 1403 leap year) —
 * never generated by the code under test.
 */
describe("pure Jalali conversion (bundle-lean display path)", () => {
  it("maps known Gregorian dates to the expected Jalali fields", () => {
    expect(jalaliParts("2024-03-20")).toEqual({ year: 1403, month: 1, day: 1 });
    expect(jalaliParts("2025-03-21")).toEqual({ year: 1404, month: 1, day: 1 });
    expect(jalaliParts("2026-03-21")).toEqual({ year: 1405, month: 1, day: 1 });
    expect(jalaliParts("2026-10-31")).toEqual({ year: 1405, month: 8, day: 9 });
    expect(jalaliParts("2025-03-20")).toEqual({ year: 1403, month: 12, day: 30 });
    expect(jalaliParts("2026-03-20")).toEqual({ year: 1404, month: 12, day: 29 });
    expect(jalaliParts("2025-06-21")).toEqual({ year: 1404, month: 3, day: 31 });
    expect(jalaliParts("2025-06-22")).toEqual({ year: 1404, month: 4, day: 1 });
  });

  it("formats for display with Persian digits, zero-padded", () => {
    expect(formatJalaliDate("2026-10-31")).toBe("۱۴۰۵/۰۸/۰۹");
    expect(formatJalaliDate("2026-03-21")).toBe("۱۴۰۵/۰۱/۰۱");
    expect(formatJalaliDate("2024-03-20")).toBe("۱۴۰۳/۰۱/۰۱");
  });

  it("keeps the defensive fallbacks of the original formatter", () => {
    expect(formatJalaliDate(null)).toBe("—");
    expect(formatJalaliDate(undefined)).toBe("—");
    expect(formatJalaliDate("")).toBe("—");
    expect(formatJalaliDate("   ")).toBe("—");
    expect(formatJalaliDate("2026-13-01")).toBe("2026-13-01");
    expect(formatJalaliDate("not-a-date")).toBe("not-a-date");
    expect(formatJalaliDate("2026-10-31T14:30:00Z")).toBe("2026-10-31T14:30:00Z");
  });

  it("round-trips a thousand years of days without losing a day", () => {
    // Sweep every calendar day from 2020-01-01 to 2030-12-31 through both
    // directions; the pair must be an exact bijection.
    let y = 2020;
    let m = 1;
    let d = 1;
    for (let i = 0; i < 4018; i += 1) {
      const j = gregorianToJalali(y, m, d);
      const back = jalaliToGregorian(j.year, j.month, j.day);
      expect([back.year, back.month, back.day], `${y}-${m}-${d}`).toEqual([y, m, d]);
      // And the forward step.
      d += 1;
      const len = m === 2 && ((y % 4 === 0 && y % 100 !== 0) || y % 400 === 0) ? 29 : ([31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1] ?? 30);
      if (d > len) {
        d = 1;
        m += 1;
        if (m > 12) {
          m = 1;
          y += 1;
        }
      }
    }
  });

  it("handles the Jalali leap year and month lengths", () => {
    expect(isLeapJalaaliYear(1403)).toBe(true);
    expect(isLeapJalaaliYear(1404)).toBe(false);
    expect(jalaliMonthLength(1403, 12)).toBe(30);
    expect(jalaliMonthLength(1404, 12)).toBe(29);
    expect(jalaliMonthLength(1405, 6)).toBe(31);
    expect(jalaliMonthLength(1405, 7)).toBe(30);
  });
});
